-- Target API: shrapnel.stereotype_create_revision (0005_stereotype_api.sql)
-- Fingerprints, superset conformance, depth, and freeze are enforced by
-- the database at COMMIT (deferred triggers, 0004_stereotype_model.sql).
BEGIN;

-- ── fields (get-or-create; type codes from the 0001 registry) ──

-- ── stereotype revisions (topological; parent = parent's head) ──
SELECT shrapnel.stereotype_create_revision('WorkRequest', NULL, NULL, ARRAY['id', 'title', 'description', 'intent', 'context', 'constraints', 'created_by', 'created_at', 'updated_at']::text[], ARRAY[]::text[]);
SELECT shrapnel.stereotype_create_revision('TesterAttestationRequest', (SELECT head_revision_id FROM shrapnel.stereotype_resolve('WorkRequest')), 'An attestation request is a work request whose ask is verification of a specific head; it inherits identity/attribution/lifecycle from WorkRequest and adds only the attestation-specific target, evidence, and dispatch-state fields.', ARRAY['request_key', 'work_ref', 'head_sha', 'evidence', 'state', 'attempts', 'id', 'title', 'description', 'intent', 'context', 'constraints', 'created_by', 'created_at', 'updated_at']::text[], ARRAY['claim_token', 'lease_until', 'terminal_reason', 'attestation_id']::text[]);

-- ── instance-storage registrations (metadata, NOT contract) ──

-- ── verification echo: what the catalog now holds ──
SELECT s.name AS stereotype_name, r.version, r.depth, r.contract_fingerprint,
       (SELECT count(*) FROM shrapnel.stereotype_field sf WHERE sf.stereotype_revision_id = r.id) AS declared_fields,
       (SELECT count(*) FROM shrapnel.stereotype_field sf2 JOIN shrapnel.stereotype_field sf3 ON sf3.stereotype_revision_id = r.parent_revision_id AND sf2.field_id = sf3.field_id WHERE sf2.stereotype_revision_id = r.id) AS inherited_fields
FROM shrapnel.stereotype_revision r JOIN shrapnel.stereotype s ON s.id = r.stereotype_id
ORDER BY s.name, r.version;

COMMIT;
