INSERT INTO shrapnel.stereotype_instance_storage (stereotype_name, storage_class, revision_ref) VALUES ('TesterAttestationRequest', 'mongodb', (SELECT id FROM shrapnel.stereotype_revision WHERE stereotype_id = (SELECT id FROM shrapnel.stereotype WHERE name = 'TesterAttestationRequest') ORDER BY version DESC LIMIT 1)) ON CONFLICT (stereotype_name) DO UPDATE SET storage_class = EXCLUDED.storage_class, revision_ref = EXCLUDED.revision_ref;
